fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    // We take ownership of `a` as `left`, compute the midpoint,
    // then `split_off` returns the tail, leaving `left` as the head.
    let mut left = a;
    let mid = left.len() / 2;
    let right = left.split_off(mid);
    (left, right)
}

fn main() {
    assert_eq!(array_split(vec![]), (vec![], vec![]));
    assert_eq!(array_split(vec![10]), (vec![], vec![10]));
    assert_eq!(array_split(vec![1, 2]), (vec![1], vec![2]));
    assert_eq!(array_split(vec![1, 2, 3, 4]), (vec![1, 2], vec![3, 4]));
    println!("All tests passed.");
}